export const ordersRouter = Router();

ordersRouter.post('/orders', requireUser, async (req, res) => {
  const parsed = NewOrder.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ error: 'invalid order' });
  return res.status(201).json(await createOrder({ userId: req.user.id, ...parsed.data }));
});

ordersRouter.get('/orders/summary', requireUser, async (req, res) => {
  return res.json(await summarizeOrders(req.user.id));
});

test('creates an order', async () => {
  const response = await request(app).post('/orders').send({ sku: 'A-1', quantity: 2 });
  expect(response.status).toBe(201);
});
